// Bộ ảnh 9 tư thế yoga (vẽ bằng AI, phong cách minh hoạ phẳng xanh dương, đã tách nền,
// nén WebP rồi nhúng base64 vào file chữ để đẩy GitHub trọn vẹn). Lưới 3x3, ô 660x520.
// Thứ tự ô: 0 Hoa Sen · 1 Cái Cây · 2 Chiến Binh II · 3 Chó Úp Mặt · 4 Nhân Sư · 5 Em Bé · 6 Cây Cầu · 7 Tam Giác · 8 Thư Giãn
export const YOGA_SHEET = 'data:image/webp;base64,';

/** background-position để hiện đúng 1 ô trong lưới 3x3 (background-size 300% 300%) */
export const posePos = (idx: number) => `${(idx % 3) * 50}% ${Math.floor(idx / 3) * 50}%`;
